var o=[{title:`Vantagens`,text:`Cada mão carrega a sua própria carga, o que torna prático o trabalho unilateral e permite ângulos de pega que uma barra fixa pode não permitir. Uma remada com um braço ou um press com um braço podem mostrar diferenças de controlo entre os seus lados. Os halteres costumam caber melhor em espaços pequenos do que uma montagem completa de barra, embora os saltos entre pesos possam ser grandes ou a escolha limitada.`},{title:`Escolher o seu peso`,text:`Escolha um par ou um único haltere que lhe permita atingir as repetições-alvo com movimento estável e algumas repetições de reserva. Como iniciante, pode precisar de cargas diferentes para remadas, roscas e press. Se o peso seguinte for demasiado pesado, primeiro acrescente repetições, amplitude ou controlo com o mais leve.`},{title:`Entrar em posição em segurança`,text:`Num supino, sente-se com os halteres seguros junto às coxas, deite-se com controlo e coloque os pesos no lugar sem os atirar. Nos levantamentos em pé, apanhe os pesos com as pernas e o tronco numa posição estável. Não largue os pesos onde possam saltar para os seus pés, danificar o chão ou atingir alguém.`},{title:`Utilizações comuns`,text:`Os agachamentos goblet e os levantamentos romenos com halteres treinam a parte inferior do corpo, as remadas e os press com apoio cobrem a parte superior, e as caminhadas com carga desenvolvem a pega e o controlo do tronco. Se tiver só um haltere, use-o para movimentos unilaterais.`},{title:`Usar o TrainUp`,text:`No Perfil, indique os pesos dos halteres que tem. O seu plano escolhe exercícios que se adaptam ao seu equipamento, espaço e altura do teto. Não prescreve pesos, por isso escolhe a carga. Se anotar as cargas depois de um treino, escreva-as sempre da mesma forma, como “12 kg por mão”.`}];var s=[{label:`Mayo Clinic: pesos livres versus máquinas de musculação`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: técnica de treino com pesos (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};